17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
107	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (dailyRegistrationLimitReached()) {
111	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
112	        }
113	        if (cityAtCapacity(owner.getCity())) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (owner.getRegistrationDate() == null) {
117	            owner.setRegistrationDate(LocalDate.now());
118	        }
119	        owner.setCity(resolveCity(owner.getCity()));
120	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
121	        owner.setMembershipNumber(membershipNumber);
122	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
123	        owner.setMembershipTier(membershipTierFor(membershipNumber));
124	        owner.setNamesakeCount(namesakeCount(owner.getLastName()));
125	        owner.setSharesHousehold(sharesHousehold(owner));
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    /**
134	     * The maximum number of owners that may be registered on any single day (by registration date).
135	     */
136	    private static final long MAX_OWNERS_PER_DAY = 20;
137	
138	    /**
139	     * Determines whether the maximum number of owners for the current day has already been reached.
140	     * Owners are counted by their registration date, so once {@value #MAX_OWNERS_PER_DAY} owners
141	     * carry today's registration date no further owners may be created today.
142	     *
143	     * @return {@code true} if today's registration limit has been reached
144	     */
145	    private boolean dailyRegistrationLimitReached() {
146	        LocalDate today = LocalDate.now();
147	        long registeredToday = this.clinicService.findAllOwners().stream()
148	            .filter(existing -> today.equals(existing.getRegistrationDate()))
149	            .count();
150	        return registeredToday >= MAX_OWNERS_PER_DAY;
151	    }
152	
153	    /**
154	     * The maximum number of owners that may be registered in any single city.
155	     */
156	    private static final long MAX_OWNERS_PER_CITY = 8;
157	
158	    /**
159	     * Determines whether the given city has already reached its capacity of
160	     * {@value #MAX_OWNERS_PER_CITY} owners. Owners are counted per city ignoring letter case, so
161	     * once a city holds {@value #MAX_OWNERS_PER_CITY} owners no further owners may be created there.
162	     *
163	     * @param city the raw city supplied for the owner being created, may be {@code null}
164	     * @return {@code true} if the city already contains the maximum number of owners
165	     */
166	    private boolean cityAtCapacity(String city) {
167	        if (city == null) {
168	            return false;
169	        }
170	        long ownersInCity = this.clinicService.findAllOwners().stream()
171	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
172	            .count();
173	        return ownersInCity >= MAX_OWNERS_PER_CITY;
174	    }
175	
176	    /**
177	     * Resolves the city to store for a newly created owner. If another owner is already stored in
178	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
179	     * city name is reused so that a single city is always represented consistently. Otherwise the
180	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
181	     *
182	     * @param city the raw city supplied for the owner being created, may be {@code null}
183	     * @return the city to store, or {@code null} if {@code city} is {@code null}
184	     */
185	    private String resolveCity(String city) {
186	        if (city == null) {
187	            return null;
188	        }
189	        return this.clinicService.findAllOwners().stream()
190	            .map(Owner::getCity)
191	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
192	            .findFirst()
193	            .orElseGet(() -> titleCase(city));
194	    }
195	
196	    /**
197	     * Title-cases a value so that the first letter of every whitespace-separated word is
198	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
199	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
200	     * {@code "London"}.
201	     *
202	     * @param value the raw value, may be {@code null}
203	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
204	     */
205	    private static String titleCase(String value) {
206	        if (value == null) {
207	            return null;
208	        }
209	        StringBuilder result = new StringBuilder(value.length());
210	        boolean startOfWord = true;
211	        for (int i = 0; i < value.length(); i++) {
212	            char c = value.charAt(i);
213	            if (Character.isWhitespace(c)) {
214	                startOfWord = true;
215	                result.append(c);
216	            } else {
217	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
218	                startOfWord = false;
219	            }
220	        }
221	        return result.toString();
222	    }
223	
224	    /**
225	     * Builds the customer code for a newly created owner in the given city, formatted as
226	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
227	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
228	     * count of existing owners in the city ignores letter case.
229	     *
230	     * @param city the city of the owner being created
231	     * @return the assigned customer code
232	     */
233	    private String nextCustomerCode(String city) {
234	        long ownersInCity = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
236	            .count();
237	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
238	    }
239	
240	    /**
241	     * The maximum membership number that still qualifies an owner for the founding tier. The
242	     * first {@value #MAX_FOUNDING_MEMBERS} owners ever created are founding members.
243	     */
244	    private static final int MAX_FOUNDING_MEMBERS = 100;
245	
246	    /**
247	     * Resolves the membership tier for a newly created owner from its sequential membership
248	     * number. The first {@value #MAX_FOUNDING_MEMBERS} owners ever created are {@code FOUNDING};
249	     * every later owner is {@code STANDARD}.
250	     *
251	     * @param membershipNumber the owner's sequential membership number
252	     * @return {@code "FOUNDING"} or {@code "STANDARD"}
253	     */
254	    private static String membershipTierFor(int membershipNumber) {
255	        return membershipNumber <= MAX_FOUNDING_MEMBERS ? "FOUNDING" : "STANDARD";
256	    }
257	
258	    /**
259	     * Counts how many existing owners already share the given last name, ignoring letter case and
260	     * surrounding or repeated whitespace. This is evaluated at the moment a new owner is created,
261	     * before that owner is stored, so it reflects the number of other owners that carry the same
262	     * last name.
263	     *
264	     * @param lastName the last name of the owner being created, may be {@code null}
265	     * @return the number of other owners already sharing that last name
266	     */
267	    private int namesakeCount(String lastName) {
268	        String normalized = normalize(lastName);
269	        return (int) this.clinicService.findAllOwners().stream()
270	            .filter(existing -> Objects.equals(normalize(existing.getLastName()), normalized))
271	            .count();
272	    }
273	
274	    /**
275	     * Determines whether another owner already shares a household with the owner being created,
276	     * meaning an existing owner already has the same address and city. Both address and city are
277	     * compared ignoring letter case and surrounding or repeated whitespace (see
278	     * {@link #normalize(String)}). This is evaluated before the new owner is stored, so it reflects
279	     * only owners that already existed.
280	     *
281	     * @param owner the candidate owner to check
282	     * @return {@code true} if a stored owner already has the same address and city
283	     */
284	    private boolean sharesHousehold(Owner owner) {
285	        String address = normalize(owner.getAddress());
286	        String city = normalize(owner.getCity());
287	        return this.clinicService.findAllOwners().stream()
288	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
289	                && Objects.equals(normalize(existing.getCity()), city));
290	    }
291	
292	    /**
293	     * Determines whether an owner already exists using the same telephone number.
294	     * Comparison ignores letter case and surrounding or repeated whitespace.
295	     *
296	     * @param owner the candidate owner to check
297	     * @return {@code true} if any other owner with the same telephone is already stored
298	     */
299	    private boolean ownerAlreadyExists(Owner owner) {
300	        String telephone = normalizeTelephone(owner.getTelephone());
301	        return this.clinicService.findAllOwners().stream()
302	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
303	    }
304	
305	    /**
306	     * Normalizes a telephone number to digits only, stripping spaces, dashes and
307	     * parentheses (any non-digit character). This is the canonical stored form and is
308	     * used for the telephone-uniqueness check, so {@code "(613) 555-0100"} and
309	     * {@code "6135550100"} are treated as the same number.
310	     *
311	     * @param telephone the raw telephone value, may be {@code null}
312	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
313	     */
314	    private static String normalizeTelephone(String telephone) {
315	        if (telephone == null) {
316	            return null;
317	        }
318	        return telephone.replaceAll("[^0-9]", "");
319	    }
320	
321	    /**
322	     * Determines whether another owner already uses the same email address.
323	     * Owners without an email are ignored, so a missing email never conflicts.
324	     * Comparison ignores letter case and surrounding or repeated whitespace.
325	     *
326	     * @param owner the candidate owner to check
327	     * @return {@code true} if the candidate supplies an email already used by a stored owner
328	     */
329	    private boolean emailAlreadyExists(Owner owner) {
330	        String email = normalize(owner.getEmail());
331	        if (email == null || email.isEmpty()) {
332	            return false;
333	        }
334	        return this.clinicService.findAllOwners().stream()
335	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
336	    }
337	
338	    /**
339	     * Normalizes a value for duplicate detection so that comparisons ignore letter
340	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
341	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
342	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
343	     * both normalize to {@code "john smith"}.
344	     *
345	     * @param value the raw value, may be {@code null}
346	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
347	     */
348	    private static String normalize(String value) {
349	        if (value == null) {
350	            return null;
351	        }
352	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
358	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
359	        if (currentOwner == null) {
360	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
361	        }
362	        currentOwner.setAddress(ownerFieldsDto.getAddress());
363	        currentOwner.setCity(ownerFieldsDto.getCity());
364	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
365	        currentOwner.setLastName(ownerFieldsDto.getLastName());
366	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
367	        this.clinicService.saveOwner(currentOwner);
368	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
369	    }
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Transactional
373	    @Override
374	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
375	        Owner owner = this.clinicService.findOwnerById(ownerId);
376	        if (owner == null) {
377	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
378	        }
379	        this.clinicService.deleteOwner(owner);
380	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
386	        Owner owner = this.clinicService.findOwnerById(ownerId);
387	        if (owner == null) {
388	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
389	        }
390	        HttpHeaders headers = new HttpHeaders();
391	        Pet pet = petMapper.toPet(petFieldsDto);
392	        owner.setId(ownerId);
393	        pet.setOwner(owner);
394	        pet.getType().setName(null);
395	        this.clinicService.savePet(pet);
396	        PetDto petDto = petMapper.toPetDto(pet);
397	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
398	            .buildAndExpand(pet.getId()).toUri());
399	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
400	    }
401	
402	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
403	    @Override
404	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
405	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
406	        if (currentOwner != null) {
407	            Pet currentPet = this.clinicService.findPetById(petId);
408	            if (currentPet != null) {
409	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
410	                currentPet.setName(petFieldsDto.getName());
411	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
412	                this.clinicService.savePet(currentPet);
413	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
414	            }
415	        }
416	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
417	    }
418	
419	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
420	    @Override
421	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
422	        HttpHeaders headers = new HttpHeaders();
423	        Visit visit = visitMapper.toVisit(visitFieldsDto);
424	        Pet pet = new Pet();
425	        pet.setId(petId);
426	        visit.setPet(pet);
427	        this.clinicService.saveVisit(visit);
428	        VisitDto visitDto = visitMapper.toVisitDto(visit);
429	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
430	            .buildAndExpand(visit.getId()).toUri());
431	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
432	    }
433	
434	
435	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
436	    @Override
437	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
438	        Owner owner = this.clinicService.findOwnerById(ownerId);
439	        if (owner != null) {
440	            Pet pet = owner.getPet(petId);
441	            if (pet != null) {
442	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
443	            }
444	        }
445	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
446	    }
447	}
